-- Modify "users" table
ALTER TABLE "users" ADD COLUMN "banned" boolean NULL, ADD COLUMN "banned_at" timestamptz NULL, ADD COLUMN "ban_ends_at" timestamptz NULL;
-- Create "reports" table
CREATE TABLE "reports" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "entity" character varying NOT NULL,
  "entity_id" bigint NOT NULL,
  "reason" text NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "target_user_id" bigint NULL,
  "target_issue_id" bigint NULL,
  "user_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "reports_issues_target_issue" FOREIGN KEY ("target_issue_id") REFERENCES "issues" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "reports_users_reports" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "reports_users_target_user" FOREIGN KEY ("target_user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "report_target_matches_entity" CHECK ((((entity)::text = 'user'::text) AND (target_issue_id IS NULL) AND ((target_user_id IS NULL) OR (target_user_id = entity_id))) OR (((entity)::text = 'issue'::text) AND (target_user_id IS NULL) AND ((target_issue_id IS NULL) OR (target_issue_id = entity_id))))
);
